Object.assign(MEMO, {
  someday:"some（某個）+ day（日子）＝將來的某一天。",
  hometown:"home（家）+ town（城鎮）＝家所在的城鎮，就是故鄉。",
  "fairy tale":"fairy（小仙子）+ tale（故事）＝有小仙子的故事，就是童話。tale 和 tail（尾巴）同音。",
  adapt:"adapt 和 adopt（領養）只差一個字母：被領養的小狗要慢慢適應新家。",
  forgetful:"forget（忘記）+ ful（充滿）＝滿腦子忘東忘西，就是健忘的。ful 只有一個 l。",
  childhood:"child（小孩）+ hood（……的時期）＝當小孩的時期，就是童年。",
  memory:"memory 和 remember（記得）是一家人：記得的事情，就是回憶。",
  "grow up":"grow（成長）+ up（往上）：一直往上長高，就是長大了。",
  kindergarten:"kinder（德文的「小孩」）+ garten（花園）＝小孩的花園，就是幼稚園。",
  "elementary school":"element 是「基本元素」：學最基本東西的學校，就是國小。",
  diary:"diary 和 daily（每天的）很像：每天寫的本子，就是日記。小心別拼成 dairy（乳製品）！",
  album:"album 唸起來像「愛爾本」：愛爾把照片一本一本收進相簿。",
  toy:"toy 唸起來像「頭一」：小時候頭一個玩具最難忘。",
  playground:"play（玩）+ ground（地面）＝玩耍的地方，就是遊樂場、操場。",
  naughty:"naughty 唸起來像「鬧體」：頑皮的孩子愛鬧，整個身體停不下來。",
  miss:"miss 是「錯過」也是「想念」：錯過了，才開始想念。",
  nickname:"nick（刻痕、小記號）+ name（名字）：大家給你的小記號名字，就是綽號。",
  "time capsule":"time（時間）+ capsule（膠囊）＝把時間裝起來的膠囊，多年後打開，回憶就跑出來了！",
  moment:"moment 裡有 mom：和媽媽在一起的每一刻都很珍貴。",
  neighborhood:"neighbor（鄰居）+ hood（區域）＝鄰居們住的區域，就是社區。",
  reunion:"re（再）+ union（聯合、在一起）＝再一次聚在一起，就是團聚、同學會。",
  graduation:"graduate 去掉 e 加 ion，變成名詞 graduation：畢業典禮。tion 唸「遜」。",
  farewell:"fare（過日子）+ well（好）：祝你以後都過得好，就是告別時說的話。",
  ceremony:"ceremony 唸起來像「誰兒摸你」：典禮上校長摸摸你的頭說恭喜。",
  diploma:"diploma 唸起來像「低撲樓媽」：拿到畢業證書，飛奔下樓撲向媽媽。",
  yearbook:"year（年）+ book（書）＝記錄這一年的書，就是畢業紀念冊。",
  "high school":"high（高的）+ school（學校）＝比國中更高一級的學校，就是高中。",
  hug:"hug 唸起來像「哈格」：哈～抱一個！",
  tear:"tear 和 ear（耳朵）只差一個 t：眼淚流過臉頰，滴到耳朵邊。",
  "keep in touch":"keep（保持）+ in touch（接觸中）：一直保持接觸，就是保持聯絡。",
  teenager:"teen 是 thirteen 到 nineteen 的尾巴，+ age（年紀）+ er（人）＝十幾歲的人，就是青少年。",
  grateful:"grate 唸起來像 great（很棒）+ ful（充滿）：心中充滿感謝，覺得一切都很棒。",
  speech:"speech 和 speak（說話）是一家人：站在台上說話，就是演講。",
  memorable:"memory（回憶）去掉 y + able（能夠……的）：能留在回憶裡的，就是難忘的。",
  custom:"custom 唸起來像「卡死疼」：老習俗卡在大家心裡，改不掉。customer 是「顧客」。",
  routine:"routine 裡有 route（路線）：每天走同樣的路線，就是例行公事。",
  tradition:"tra + dition：一代一代傳（tra）下來的，就是傳統。字尾 tion 唸「遜」。",
  traditional:"tradition（傳統）+ al（形容詞字尾）＝傳統的。",
  "get used to":"get（變得）+ used to（習慣）：慢慢變得習慣。to 是介系詞，後面接 V-ing！",
  develop:"de（解開）+ velop（包起來）：把包起來的東西慢慢打開，就是發展。",
  behavior:"behave（守規矩）的名詞：你守不守規矩，看的就是你的行為。",
  attitude:"attitude 唸起來像「愛的球的」：用愛的態度對待每一顆球。",
  lifestyle:"life（生活）+ style（風格）＝生活的風格，就是生活方式。",
  instead:"in + stead（位置）：站到別人的位置上，就是「代替、改為」。",
  anymore:"any（任何）+ more（更多）：not ... anymore，連一點點都不再有了。",
  "no longer":"no（不）+ longer（更久）：不再更久下去了，就是「不再」。",
  wish:"wish 唸起來像「咻」：許願時把願望「咻」地送上天。",
  lottery:"lot（籤）+ tery：抽籤決定誰中大獎，就是樂透。",
  rich:"rich 唸起來像「瑞去」：有錢人搭飛機去瑞士玩。",
  superpower:"super（超級）+ power（力量）＝超級力量，就是超能力。",
  genius:"genius 裡有 gen（生出來）：天生就很聰明的人，就是天才。",
  millionaire:"million（百萬）+ aire（……的人）＝有百萬元的人，就是百萬富翁。",
  "time machine":"time（時間）+ machine（機器）＝穿越時間的機器，就是時光機。",
  pretend:"pre（先）+ tend（伸出）：先把假的樣子伸出來給別人看，就是假裝。",
  natural:"nature（自然）去掉 e + al ＝自然的。注意 a 從長 a 變成短 a。",
  national:"nation（國家）+ al ＝國家的。nation 唸長 a，national 唸短 a。",
  personal:"person（人）+ al ＝個人的。",
  available:"a + vail（用處）+ able（可以）：可以拿來用的，就是可取得的、有空的。",
  valuable:"value（價值）去掉 e + able ＝有價值的、貴重的。",
  enjoyable:"enjoy（享受）+ able（可以）＝可以享受的，就是令人愉快的。",
  suitable:"suit（西裝；適合）+ able：像量身訂做的西裝一樣，剛剛好適合。",
  meaningful:"meaning（意義）+ ful（充滿）＝充滿意義的。",
  unforgettable:"un（不）+ forget（忘記）+ t + able（能夠）＝不能忘記的，就是難以忘懷的。",
  adult:"adult 唸起來像「呃大偶」：長大了的玩偶，就是大人。",
  remind:"re（再）+ mind（心思）：讓你的心思再想一次，就是提醒。",
  regret:"re（回頭）+ gret（像 great）：回頭一想，覺得當初沒那麼 great，就後悔了。",
  opportunity:"op（朝向）+ port（港口）+ unity：風把船吹向港口，正是靠岸的好機會。",
  recall:"re（回來）+ call（呼叫）：把記憶呼叫回來，就是回想。",
});
